import React, { useState, useEffect } from 'react';
import { LogIn, LogOut, User, Users, Plus, Edit, Trash2, Save, X, RotateCw } from 'lucide-react';

// --- Mock Data and API Simulation ---

const mockInventory = [
  { id: 101, name: 'Paracetamol 500mg', description: 'Pain and fever relief', price: 15.50, stock: 120, category: 'Tablets' },
  { id: 102, name: 'Amoxicillin 250mg', description: 'Broad-spectrum antibiotic', price: 85.00, stock: 55, category: 'Capsules' },
  { id: 103, name: 'Cough Syrup (DM)', description: 'Relief from dry cough', price: 150.00, stock: 75, category: 'Syrups' },
  { id: 104, name: 'Band-Aid Strips', description: 'First aid bandage', price: 30.00, stock: 200, category: 'Topicals' },
];

const mockUsers = {
  admin: { username: 'admin', role: 'admin', password: 'password123' },
  user: { username: 'user', role: 'user', password: 'password123' },
};

// Utility to simulate network delay
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

// Simulated CRUD functions (Admin Only)
const api = {
    fetchMedicines: async () => {
        await delay(500);
        return [...JSON.parse(localStorage.getItem('inventory') || '[]')];
    },
    saveMedicines: async (newInventory) => {
        await delay(300);
        localStorage.setItem('inventory', JSON.stringify(newInventory));
        return true;
    }
};

// --- Main Application Component ---

const App = () => {
  const [inventory, setInventory] = useState([]);
  const [user, setUser] = useState(null); // {username, role}
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [isDataLoading, setIsDataLoading] = useState(false);
  const [currentPage, setCurrentPage] = useState('login');
  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState('add'); // 'add' or 'edit'
  const [currentMedicine, setCurrentMedicine] = useState(null); // For editing

  // Initialize inventory from localStorage on mount
  useEffect(() => {
    const storedInventory = localStorage.getItem('inventory');
    if (!storedInventory || JSON.parse(storedInventory).length === 0) {
      localStorage.setItem('inventory', JSON.stringify(mockInventory));
      setInventory(mockInventory);
    } else {
      setInventory(JSON.parse(storedInventory));
    }
    // Simulate initial auth check (since we are not using Firebase)
    const storedUser = JSON.parse(localStorage.getItem('currentUser'));
    if (storedUser) {
      setUser(storedUser);
      setCurrentPage(storedUser.role === 'admin' ? 'admin_dashboard' : 'user_dashboard');
    } else {
      setCurrentPage('login');
    }
    setIsAuthLoading(false);
  }, []);

  // --- State/Page Management ---

  const goTo = (page) => setCurrentPage(page);
  const role = user?.role;

  // --- Authentication Handlers ---

  const handleLogin = async (username, password) => {
    setIsAuthLoading(true);
    await delay(700);
    const mockUser = mockUsers[username];

    if (mockUser && mockUser.password === password) {
      const userData = { username: mockUser.username, role: mockUser.role };
      setUser(userData);
      localStorage.setItem('currentUser', JSON.stringify(userData));
      goTo(mockUser.role === 'admin' ? 'admin_dashboard' : 'user_dashboard');
    } else {
      alert('Login failed. Check username/password.');
    }
    setIsAuthLoading(false);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('currentUser');
    goTo('login');
  };

  // --- CRUD Handlers ---

  const fetchInventory = async () => {
    setIsDataLoading(true);
    try {
      const data = await api.fetchMedicines();
      setInventory(data);
    } catch (e) {
      console.error("Failed to fetch inventory:", e);
    } finally {
      setIsDataLoading(false);
    }
  };

  const handleSave = async (medicine) => {
    setIsDataLoading(true);
    let newInventory;

    if (modalMode === 'add') {
      // Simulate ID generation
      const newId = Math.max(...inventory.map(m => m.id), 100) + 1;
      newInventory = [...inventory, { ...medicine, id: newId, stock: Number(medicine.stock), price: Number(medicine.price) }];
    } else if (modalMode === 'edit') {
      newInventory = inventory.map(m =>
        m.id === medicine.id ? { ...medicine, stock: Number(medicine.stock), price: Number(medicine.price) } : m
      );
    }

    try {
      await api.saveMedicines(newInventory);
      setInventory(newInventory);
      setShowModal(false);
    } catch (e) {
      console.error("Failed to save data:", e);
    } finally {
      setIsDataLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this item?')) return;

    setIsDataLoading(true);
    const newInventory = inventory.filter(m => m.id !== id);

    try {
      await api.saveMedicines(newInventory);
      setInventory(newInventory);
    } catch (e) {
      console.error("Failed to delete data:", e);
    } finally {
      setIsDataLoading(false);
    }
  };

  const openAddModal = () => {
    setModalMode('add');
    setCurrentMedicine({ name: '', description: '', price: 0, stock: 0, category: '' });
    setShowModal(true);
  };

  const openEditModal = (med) => {
    setModalMode('edit');
    setCurrentMedicine(med);
    setShowModal(true);
  };

  // --- Shared Components ---

  const Header = ({ title }) => (
    <div className="flex justify-between items-center p-4 bg-white border-b border-gray-200 shadow-sm sticky top-0 z-10">
      <div className="flex items-center space-x-3">
        <h1 className="text-3xl font-extrabold text-indigo-700 flex items-center">
          <img src="https://placehold.co/40x40/6366f1/ffffff/png?text=Rx" alt="Rx Icon" className="mr-3 rounded-full"/>
          {title}
        </h1>
        {role && (
          <span className={`px-3 py-1 text-xs font-semibold rounded-full ${role === 'admin' ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'}`}>
            {role.toUpperCase()}
          </span>
        )}
      </div>

      <div className="flex space-x-3">
        {user && (
          <>
            <button
              onClick={() => goTo(role === 'admin' ? 'admin_dashboard' : 'user_dashboard')}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition duration-150 flex items-center"
            >
              <Users className="w-4 h-4 mr-2" />
              Dashboard
            </button>
            <button
              onClick={handleLogout}
              className="px-4 py-2 text-sm font-medium text-white bg-red-500 rounded-lg hover:bg-red-600 transition duration-150 flex items-center shadow-md"
            >
              <LogOut className="w-4 h-4 mr-2" />
              Logout ({user.username})
            </button>
          </>
        )}
      </div>
    </div>
  );

  const MedicineTable = ({ data, showActions = false, onEdit, onDelete }) => {
    const [searchTerm, setSearchTerm] = useState('');

    const filteredData = data.filter(med =>
      med.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      med.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      med.id.toString().includes(searchTerm)
    );

    return (
      <div className="mt-6 p-4 bg-white rounded-xl shadow-2xl">
        <div className="flex justify-between items-center mb-4">
            <input
                type="text"
                placeholder="Search by name, ID, or description..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-1/3 p-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 transition duration-150"
            />
            {showActions && (
                <button
                    onClick={openAddModal}
                    className="flex items-center px-4 py-2 text-sm font-semibold text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 transition duration-150 shadow-md"
                >
                    <Plus className="w-4 h-4 mr-2" /> Add New Medicine
                </button>
            )}
        </div>
        {isDataLoading ? (
            <div className="flex justify-center items-center h-48">
                <RotateCw className="w-8 h-8 text-indigo-500 animate-spin" />
                <p className="ml-3 text-lg text-indigo-500">Loading Inventory...</p>
            </div>
        ) : (
            <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-indigo-50">
                        <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-indigo-700 uppercase tracking-wider">ID</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-indigo-700 uppercase tracking-wider">Name</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-indigo-700 uppercase tracking-wider">Description</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-indigo-700 uppercase tracking-wider">Category</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-indigo-700 uppercase tracking-wider">Price (₹)</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-indigo-700 uppercase tracking-wider">Stock</th>
                            {showActions && <th className="px-6 py-3 text-center text-xs font-medium text-indigo-700 uppercase tracking-wider">Actions</th>}
                        </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {filteredData.length > 0 ? (
                            filteredData.map((med) => (
                                <tr key={med.id} className="hover:bg-gray-50 transition duration-150">
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{med.id}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-800 font-semibold">{med.name}</td>
                                    <td className="px-6 py-4 text-sm text-gray-500 max-w-xs truncate">{med.description}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-indigo-600">{med.category}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-700 font-mono">₹{med.price.toFixed(2)}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-bold" style={{ color: med.stock < 20 ? '#ef4444' : '#10b981' }}>
                                        {med.stock}
                                    </td>
                                    {showActions && (
                                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-center">
                                            <button
                                                onClick={() => onEdit(med)}
                                                className="inline-flex items-center text-indigo-600 hover:text-indigo-900 mr-3 transition duration-150"
                                                aria-label="Edit"
                                            >
                                                <Edit className="w-4 h-4" />
                                            </button>
                                            <button
                                                onClick={() => onDelete(med.id)}
                                                className="inline-flex items-center text-red-600 hover:text-red-900 transition duration-150"
                                                aria-label="Delete"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </td>
                                    )}
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan={showActions ? 7 : 6} className="px-6 py-8 text-center text-lg text-gray-500">
                                    No medicines found matching "{searchTerm}".
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        )}
      </div>
    );
  };

  const AuthForm = ({ onLogin }) => {
    const [username, setUsername] = useState('user');
    const [password, setPassword] = useState('password123');
    const [isRegister, setIsRegister] = useState(false);

    const handleSubmit = (e) => {
      e.preventDefault();
      if (isRegister) {
        alert("Registration is currently disabled in this demo. Please use the existing credentials.");
      } else {
        onLogin(username, password);
      }
    };

    return (
      <div className="flex items-center justify-center min-h-screen bg-gray-100">
        <div className="w-full max-w-md p-8 space-y-8 bg-white rounded-xl shadow-2xl border-t-4 border-indigo-600">
          <div className="text-center">
            <h2 className="text-3xl font-extrabold text-gray-900 flex items-center justify-center">
                <LogIn className="w-6 h-6 mr-2 text-indigo-600"/>
                {isRegister ? 'Register Account' : 'Sign In'}
            </h2>
            <p className="mt-2 text-sm text-gray-600">
              {isRegister ? 'Create an account' : 'Access the Inventory System'}
            </p>
          </div>
          <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
            <div>
              <label htmlFor="username" className="text-sm font-medium text-gray-700 block mb-1">Username</label>
              <input
                id="username"
                type="text"
                required
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 transition duration-150"
                placeholder="admin or user"
              />
            </div>
            <div>
              <label htmlFor="password" className="text-sm font-medium text-gray-700 block mb-1">Password</label>
              <input
                id="password"
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 transition duration-150"
                placeholder="password123"
              />
            </div>

            <div className="space-y-4">
              <button
                type="submit"
                disabled={isAuthLoading}
                className="w-full flex justify-center items-center py-2 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 transition duration-150 disabled:opacity-50"
              >
                {isAuthLoading ? <RotateCw className="w-4 h-4 animate-spin mr-2" /> : <LogIn className="w-4 h-4 mr-2" />}
                {isAuthLoading ? 'Loading...' : (isRegister ? 'Register' : 'Login')}
              </button>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Demo Credentials:</span>
                <span className="font-semibold text-indigo-600">admin / user</span>
              </div>
            </div>
          </form>
          <div className="text-center">
            <button
              onClick={() => setIsRegister(!isRegister)}
              className="text-sm text-indigo-600 hover:text-indigo-500 font-medium transition duration-150"
            >
              {isRegister ? 'Already have an account? Sign In' : 'Need an account? Register (Disabled)'}
            </button>
          </div>
        </div>
      </div>
    );
  };

  const InventoryModal = ({ mode, medicine, onSave, onClose }) => {
    const [formData, setFormData] = useState(medicine);

    const handleChange = (e) => {
      const { name, value } = e.target;
      setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleSubmit = (e) => {
      e.preventDefault();
      // Simple validation
      if (formData.name.trim() === '' || Number(formData.price) <= 0 || Number(formData.stock) < 0) {
        alert('Please ensure Name is entered and Price/Stock are valid numbers.');
        return;
      }
      onSave(formData);
    };

    const title = mode === 'add' ? 'Add New Medicine' : `Edit Medicine: ${formData.name}`;

    return (
      <div className="fixed inset-0 bg-gray-600 bg-opacity-75 flex justify-center items-center z-50 p-4">
        <div className="bg-white rounded-xl shadow-3xl w-full max-w-lg p-6 transform transition-all scale-100 border-t-8 border-indigo-500">
          <div className="flex justify-between items-center border-b pb-3 mb-4">
            <h3 className="text-xl font-bold text-gray-800 flex items-center">
                {mode === 'add' ? <Plus className="w-5 h-5 mr-2 text-indigo-600" /> : <Edit className="w-5 h-5 mr-2 text-indigo-600" />}
                {title}
            </h3>
            <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1 rounded-full bg-gray-50 hover:bg-gray-100 transition duration-150">
              <X className="w-5 h-5" />
            </button>
          </div>
          <form onSubmit={handleSubmit} className="space-y-4">
            {mode === 'edit' && (
                <div className="text-sm text-gray-500 mb-4">ID: <span className="font-mono font-semibold text-gray-700">{formData.id}</span></div>
            )}
            <div>
              <label className="block text-sm font-medium text-gray-700">Name</label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                required
                className="mt-1 block w-full border border-gray-300 rounded-lg p-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Description</label>
              <textarea
                name="description"
                value={formData.description}
                onChange={handleChange}
                rows="2"
                className="mt-1 block w-full border border-gray-300 rounded-lg p-2 focus:ring-indigo-500 focus:border-indigo-500"
              ></textarea>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Category</label>
              <input
                type="text"
                name="category"
                value={formData.category}
                onChange={handleChange}
                className="mt-1 block w-full border border-gray-300 rounded-lg p-2 focus:ring-indigo-500 focus:border-indigo-500"
                placeholder="e.g., Tablets, Syrups"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700">Price (₹)</label>
                <input
                  type="number"
                  name="price"
                  value={formData.price}
                  onChange={handleChange}
                  step="0.01"
                  min="0"
                  required
                  className="mt-1 block w-full border border-gray-300 rounded-lg p-2 focus:ring-indigo-500 focus:border-indigo-500"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700">Stock</label>
                <input
                  type="number"
                  name="stock"
                  value={formData.stock}
                  onChange={handleChange}
                  min="0"
                  required
                  className="mt-1 block w-full border border-gray-300 rounded-lg p-2 focus:ring-indigo-500 focus:border-indigo-500"
                />
              </div>
            </div>
            <div className="pt-4 flex justify-end space-x-3">
              <button
                type="button"
                onClick={onClose}
                className="flex items-center px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition duration-150"
              >
                <X className="w-4 h-4 mr-2" /> Cancel
              </button>
              <button
                type="submit"
                disabled={isDataLoading}
                className="flex items-center px-4 py-2 text-sm font-medium text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 transition duration-150 shadow-md disabled:opacity-50"
              >
                {isDataLoading ? <RotateCw className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                {mode === 'add' ? 'Create' : 'Save Changes'}
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  };

  // --- Page Views ---

  const UserDashboard = () => (
    <div className="p-8 max-w-7xl mx-auto">
      <h2 className="text-3xl font-bold text-gray-800 mb-6 flex items-center">
        <User className="w-6 h-6 mr-3 text-green-600" /> User Inventory View
      </h2>
      <MedicineTable
        data={inventory}
        showActions={false}
      />
    </div>
  );

  const AdminDashboard = () => (
    <div className="p-8 max-w-7xl mx-auto">
      <h2 className="text-3xl font-bold text-gray-800 mb-6 flex items-center">
        <Users className="w-6 h-6 mr-3 text-red-600" /> Admin Management Panel
      </h2>
      <MedicineTable
        data={inventory}
        showActions={true}
        onEdit={openEditModal}
        onDelete={handleDelete}
      />
    </div>
  );

  // --- Main Render Logic ---

  if (isAuthLoading) {
    return (
        <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100">
            <RotateCw className="w-10 h-10 text-indigo-500 animate-spin" />
            <p className="mt-4 text-xl font-medium text-indigo-700">Initializing Application...</p>
        </div>
    );
  }

  let content;
  let title = 'Medicine Inventory System';

  if (!user) {
    content = <AuthForm onLogin={handleLogin} />;
    title = 'Login/Register';
  } else {
    switch (currentPage) {
      case 'user_dashboard':
        content = <UserDashboard />;
        title = 'User Dashboard';
        break;
      case 'admin_dashboard':
        content = <AdminDashboard />;
        title = 'Admin Dashboard';
        break;
      default:
        content = <div className="text-center p-8">Page Not Found.</div>;
    }
  }

  // Render structure
  return (
    <div className="min-h-screen bg-gray-100 font-[Inter]">
      {/* Conditionally render header only when logged in or on specific views */}
      {user && <Header title={title} />}

      {/* Main Content Area */}
      {content}

      {/* CRUD Modal */}
      {showModal && currentMedicine && (
        <InventoryModal
          mode={modalMode}
          medicine={currentMedicine}
          onSave={handleSave}
          onClose={() => setShowModal(false)}
        />
      )}
    </div>
  );
};

export default App;
